code='''def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    by_row = {}
    by_col = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
        by_col.setdefault(c, []).append(r)
    # The aligned pair forms the trunk; attach all remaining points to it.
    row_candidates = [(len(cs), r, min(cs), max(cs)) for r, cs in by_row.items() if len(cs) >= 2]
    col_candidates = [(len(rs), c, min(rs), max(rs)) for c, rs in by_col.items() if len(rs) >= 2]
    if row_candidates:
        _, trunk, lo, hi = max(row_candidates)
        for c in range(lo, hi + 1):
            if out[trunk][c] == 0:
                out[trunk][c] = 3
        for r, c in points:
            for rr in range(min(r, trunk), max(r, trunk) + 1):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    elif col_candidates:
        _, trunk, lo, hi = max(col_candidates)
        for r in range(lo, hi + 1):
            if out[r][trunk] == 0:
                out[r][trunk] = 3
        for r, c in points:
            for cc in range(min(c, trunk), max(c, trunk) + 1):
                if out[r][cc] == 0:
                    out[r][cc] = 3
    return out
'''
